import {Routes} from '@angular/router';
import {patientGuard} from './guards/patient.guard';

export const routes: Routes = [
  {path: '', redirectTo: 'search', pathMatch: 'full'},
  {path: 'search', loadComponent: () => import('./search/search').then(m => m.Search)},
  {
    path: 'patient/:personId/:encntrId',
    loadComponent: () => import('./patient-summary/patient-summary').then(m => m.PatientSummary),
    canActivate: [patientGuard]
  },
  {path: 'config', loadComponent: () => import('./config/config').then(m => m.Config)},
  {path: '**', redirectTo: 'search'}
];
