import {ChangeDetectionStrategy, Component, inject, OnInit} from '@angular/core';
import {Router, RouterOutlet} from '@angular/router';
import {CUSTOM_DATE_FORMATS} from './app.config';
import {buildVersion} from './version';
import {
  MPageService,
  MpageLogComponent,
  TabbedMenuComponent,
  IMenuItem,
  AddressService,
  AllergyService,
  CodeValueService,
  ConfigService,
  CustomService,
  DiagnosisService,
  EncounterService,
  Dialog,
  OrganizationService,
  PersonService,
  PhoneService,
  ProblemService,
  ReferenceService,
  PrsnlService
} from '@clinicaloffice/mpage-developer';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, MpageLogComponent, TabbedMenuComponent],
  templateUrl: './app.html',
  styleUrl: './app.scss',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [MPageService, AddressService, AllergyService, CodeValueService, CustomService,
    DiagnosisService, EncounterService, Dialog, OrganizationService, PersonService, PhoneService,
    ProblemService, PrsnlService, ReferenceService]
})
export class App implements OnInit {
  public MPage = inject(MPageService);
  private router = inject(Router);

  readonly version = buildVersion;

  readonly tabs: IMenuItem[] = [
    {idName: 'search', label: 'Patient Search', icon: 'search'},
    {idName: 'patient', label: 'Patient Summary', icon: 'person'},
    {idName: 'config', label: 'Configuration', icon: 'settings'}
  ];

  ngOnInit() {
    this.MPage.setMaxInstances(4, true, 'ORGANIZER', false);
    this.MPage.defaultDateFormats = CUSTOM_DATE_FORMATS;
  }

  onTabClick(tab: IMenuItem) {
    switch (tab.idName) {
      case 'search':
        this.router.navigate(['/search']);
        break;
      case 'config':
        this.router.navigate(['/config']);
        break;
      case 'patient':
        // Patient Summary requires route params from search — do not navigate directly
        break;
    }
  }
}
